(()=>{const $=s=>document.querySelector(s),pages=['home','levels','editor','profile','settings'],key='gdps-editor-projects-v1';let projects=[];try{projects=JSON.parse(localStorage.getItem(key)||'[]')}catch{}function go(p){pages.forEach(x=>$('#page-'+x).classList.toggle('active',x===p));document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));if(p==='home'||p==='levels')render();if(p==='profile')stats();if(p==='editor')setTimeout(()=>window.dispatchEvent(new Event('resize')),50);window.scrollTo(0,0)}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));setTimeout(()=>$('#bootScreen').classList.add('boot-done'),1400);function save(){const d={name:$('#nameInput').value.trim()||'Без названия',background:$('#bgSelect').value,objects:window.GDPSLevel.getObjects(),updated:Date.now()},i=projects.findIndex(x=>x.name===d.name);if(i<0)projects.unshift(d);else projects[i]=d;localStorage.setItem(key,JSON.stringify(projects));render();stats();$('#saveState').textContent='СОХРАНЕНО ЛОКАЛЬНО'}$('#saveBtn').onclick=save;function card(p){const el=document.createElement('article');el.className='level-card';const art=document.createElement('div');art.className='level-preview '+p.background;art.innerHTML='<span>◆</span><small>GDPS / LEVEL</small>';const info=document.createElement('div');info.className='level-info';const title=document.createElement('b');title.textContent=p.name;const meta=document.createElement('small');meta.textContent=(p.objects?.length||0)+' объектов · '+new Date(p.updated).toLocaleDateString('ru-RU');const actions=document.createElement('div');actions.className='level-actions';const open=document.createElement('button');open.textContent='ОТКРЫТЬ';open.onclick=()=>{window.GDPSLevel.load(p);$('#nameInput').value=p.name;go('editor')};const del=document.createElement('button');del.textContent='УДАЛИТЬ';del.onclick=()=>{projects=projects.filter(x=>x!==p);localStorage.setItem(key,JSON.stringify(projects));render();stats()};actions.append(open,del);info.append(title,meta,actions);el.append(art,info);return el}function render(){const q=($('#levelSearch')?.value||'').toLowerCase(),list=projects.filter(p=>p.name.toLowerCase().includes(q));if($('#levelSort')?.value==='name')list.sort((a,b)=>a.name.localeCompare(b.name));[['recentList',projects.slice(0,3)],['allLevels',list]].forEach(([id,arr])=>{const node=$('#'+id);node.replaceChildren();arr.forEach(p=>node.append(card(p)));if(!arr.length){const empty=document.createElement('div');empty.className='empty-card';empty.textContent='Пока нет проектов. Создай свой первый уровень!';node.append(empty)}})}function stats(){$('#statLevels').textContent=projects.length;$('#statObjects').textContent=projects.reduce((n,p)=>n+(p.objects?.length||0),0)}$('#levelSearch').oninput=render;$('#levelSort').onchange=render;$('#settingGrid').onchange=e=>{$('#gridToggle').checked=e.target.checked;$('#gridToggle').dispatchEvent(new Event('change'))};$('#settingSnap').onchange=e=>$('#snapToggle').checked=e.target.checked;$('#settingMotion').onchange=e=>document.body.classList.toggle('no-motion',!e.target.checked);$('#settingTheme').onchange=e=>document.documentElement.dataset.theme=e.target.value;render();stats()})();